const item = $input.first();
const body = (item.json.snippet || item.json.textPlain || '').replace(/<[^>]*>/g, '');
const fromRaw = item.json.from || '';

const emailMatch = fromRaw.match(/<(.+?)>/);
const emailClient = emailMatch ? emailMatch[1] : fromRaw.trim();

const nomMatch = body.match(/(?:je suis|bonjour[,\s]+(?:je suis)?|nom\s*:?\s*)([A-Z\u00C0-\u00DC][a-z\u00E0-\u00FC]+(?:\s[A-Z\u00C0-\u00DC][a-z\u00E0-\u00FC]+)?)/i);
const produitMatch = body.match(/(?:commande[r]?|voudrais?|souhaite)\s+(?:\d+\s+)?(?:pot[s]? de |bocal[s]? de |kg de |g de )?([a-zA-Z\u00C0-\u017E][\w\s\-]{3,40}?)(?:\s*(?:\d|\n|,|\.|de|pour|à|merci))/i);
const qteMatch = body.match(/(\d+)\s*(?:unit[ée][s]?|pi[eè]ce[s]?|pot[s]?|bocal[s]?|kg|gramme[s]?|exemplaire[s]?)/);
const adresseMatch = body.match(/(?:adresse|livrer?\s+[àa]|livraison\s*:?\s*)([\w\s,\-\u00C0-\u017E]{10,120})/i);

return [{
  json: {
    email_from: fromRaw,
    email_client: emailClient,
    email_subject: item.json.subject || '',
    email_received_at: item.json.date || new Date().toISOString(),
    email_id: item.json.id || '',
    nom_client: nomMatch ? nomMatch[1].trim() : null,
    produit: produitMatch ? produitMatch[1].trim() : null,
    quantite: qteMatch ? parseInt(qteMatch[1]) : 1,
    adresse_livraison: adresseMatch ? adresseMatch[1].trim() : null,
    raw_body_preview: body.substring(0, 300)
  }
}];

